<?php require_once __DIR__.'/professional_assets/bootstrap_portal.php'; require_role(['admin','worker']);
$con->query("CREATE TABLE IF NOT EXISTS inventory_items(id INT AUTO_INCREMENT PRIMARY KEY,item_name VARCHAR(150) NOT NULL,category VARCHAR(100) DEFAULT '',unit VARCHAR(30) DEFAULT 'unit',quantity INT DEFAULT 0,reorder_level INT DEFAULT 0,supplier VARCHAR(150) DEFAULT '',expiry_date DATE NULL,status VARCHAR(30) DEFAULT 'Active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(quantity),INDEX(expiry_date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$s=$con->prepare("INSERT INTO inventory_items(item_name,category,unit,quantity,reorder_level,supplier,expiry_date) VALUES(?,?,?,?,?,?,?)");$n=trim($_POST['item_name']);$c=trim($_POST['category']);$u=trim($_POST['unit']);$q=(int)$_POST['quantity'];$r=(int)$_POST['reorder_level'];$sp=trim($_POST['supplier']);$e=$_POST['expiry_date']?:null;$s->bind_param('sssiiss',$n,$c,$u,$q,$r,$sp,$e);if($s->execute())$msg='Inventory item added.';}
$rows=$con->query('SELECT * FROM inventory_items ORDER BY item_name');?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="professional_assets/app.css"><link rel="stylesheet" href="professional_assets/theme.css.php"><title>Inventory</title></head><body class="module-body"><div class="module-wrap"><div class="module-head"><div><span class="eyebrow">GENERAL INVENTORY</span><h1>Hospital Inventory</h1><p>Equipment, consumables, suppliers, stock and expiry.</p></div></div><?php if($msg):?><div class="success"><?=$msg?></div><?php endif;?><div class="panel"><h2>Add inventory item</h2><form method="post" class="form-grid"><label>Item name<input name="item_name" required></label><label>Category<input name="category" placeholder="Equipment, consumable..."></label><label>Unit<input name="unit" value="unit"></label><label>Quantity<input type="number" name="quantity" min="0" value="0"></label><label>Reorder level<input type="number" name="reorder_level" min="0" value="10"></label><label>Supplier<input name="supplier"></label><label>Expiry date<input type="date" name="expiry_date"></label><button class="primary-btn">Add item</button></form></div><div class="panel"><h2>Current stock</h2><div class="table-wrap"><table><thead><tr><th>Item</th><th>Category</th><th>Unit</th><th>Quantity</th><th>Reorder</th><th>Supplier</th><th>Expiry</th></tr></thead><tbody><?php while($r=$rows->fetch_assoc()):?><tr><td><?=esc($r['item_name'])?></td><td><?=esc($r['category'])?></td><td><?=esc($r['unit'])?></td><td class="<?=((int)$r['quantity']<=(int)$r['reorder_level'])?'danger-text':''?>"><?=($r['quantity'])?></td><td><?=($r['reorder_level'])?></td><td><?=esc($r['supplier'])?></td><td><?=esc($r['expiry_date']??'')?></td></tr><?php endwhile;?></tbody></table></div></div></div></body></html>
